using System.Text;
using UnityEngine;

public class FishRendererDump
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();
        Renderer[] renderers = Object.FindObjectsOfType<Renderer>();

        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer r = renderers[i];
            Material m = r.sharedMaterial;
            Bounds b = r.bounds;

            sb.AppendLine(r.GetType().Name + " " + r.name +
                          " | ctr(" + b.center.x.ToString("0.00") + "," + b.center.y.ToString("0.00") + "," + b.center.z.ToString("0.00") + ")" +
                          " size(" + b.size.x.ToString("0.00") + "," + b.size.y.ToString("0.00") + "," + b.size.z.ToString("0.00") + ")" +
                          " | mat=" + (m != null ? m.name + "/" + m.shader.name : "NONE") +
                          " | order=" + r.sortingOrder + " layer=" + LayerMask.LayerToName(r.gameObject.layer));
        }

        Debug.Log("[FishRendererDump]\n" + sb);
    }
}
